FROM python:3.12-slim-bookworm
ARG SOURCE_COMMIT
LABEL org.opencontainers.image.source="https://github.com/alerta/alerta" \
      org.opencontainers.image.revision="${SOURCE_COMMIT}"
ENV PYTHONDONTWRITEBYTECODE=1 PYTHONUNBUFFERED=1 FLASK_SKIP_DOTENV=1
RUN apt-get update && apt-get install -y --no-install-recommends build-essential libpq-dev
WORKDIR /app
COPY . .
RUN python -m pip install --no-cache-dir -r requirements.txt gunicorn==23.0.0 && \
    python -m pip install --no-cache-dir --no-deps . && \
    useradd --system --uid 10001 --no-create-home alerta
USER 10001
EXPOSE 8080
CMD ["gunicorn", "--bind", "0.0.0.0:8080", "--workers", "2", "--threads", "4", "--timeout", "60", "--access-logfile", "-", "--error-logfile", "-", "alerta:create_app()"]
