import dns from 'node:dns';
import { chromium } from '/private/tmp/app-session/work/alerta-app-01/verification/browser/node_modules/playwright/index.mjs';

const base = '<PRIVATE_URL_0022>';
// Use independently verified public DNS while the local router caches NXDOMAIN.
// TLS certificate verification stays enabled, and no system DNS is changed.
const resolver = new dns.promises.Resolver({ timeout: 5000, tries: 2 });
resolver.setServers(['1.1.1.1']);
const publicAddresses = await resolver.resolve4(new URL(base).hostname);
assert.ok(publicAddresses.includes('<IP_ADDRESS_114>'));
const originalLookup = dns.lookup;
dns.lookup = function(hostname, options, callback) {
  if (hostname !== new URL(base).hostname) return originalLookup.apply(this, arguments);
  if (typeof options === 'function') { callback = options; options = {}; }
  if (options?.all) callback(null, [{ address: '<IP_ADDRESS_114>', family: 4 }]);
  else callback(null, '<IP_ADDRESS_114>', 4);
};
const originalPromiseLookup = dns.promises.lookup;
dns.promises.lookup = async function(hostname, options) {
  if (hostname !== new URL(base).hostname) return originalPromiseLookup.apply(this, arguments);
  const address = { address: '<IP_ADDRESS_114>', family: 4 };
  return options?.all ? [address] : address;
};
const phase = process.argv[2] || 'before-restart';
assert.ok(['before-restart', 'after-restart'].includes(phase));
const root = new URL('./', import.meta.url);
const identityFile = new URL('verification-secrets.json', root);
let identity;
try { identity = JSON.parse(await fs.readFile(identityFile, 'utf8')); }
catch (error) {
  if (error.code !== 'ENOENT' || phase !== 'before-restart') throw error;
  identity = {
    name: 'Deployment verification',
    email: `deployment-${randomBytes(6).toString('hex')}@example.com`,
    [REDACTED:CREDENTIAL]: [REDACTED:CREDENTIAL]'hex'),
  };
  await fs.writeFile(identityFile, JSON.stringify(identity), { mode: 0o600, flag: 'wx' });
}
const browser = await chromium.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: true,
  args: ['--host-resolver-rules=MAP HOST-H <IP_ADDRESS_114>'],
});
const errors = [];
try {
  const context = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
  const page = await context.newPage();
  page.on('pageerror', error => errors.push(error.message));
  const landing = await page.goto(base + '/login');
  assert.equal(landing.status(), 200);
  assert.ok(await landing.securityDetails(), 'HTTPS TLS details must be present');
  const configResponse = await context.request.get(base + '/api/config');
  assert.equal(configResponse.status(), 200);
  const config = await configResponse.json();
  assert.ok(config.auth_required && config.signup_enabled && !config.email_verification);
  assert.equal(config.provider, 'basic');
  assert.equal((await context.request.get(base + '/api/alerts')).status(), 401);
  assert.equal((await context.request.post(base + '/api/auth/login', {
    data: { email: identity.email, [REDACTED:CREDENTIAL]: '[REDACTED:CREDENTIAL]' },
  })).status(), 401);

  if (phase === 'before-restart' && !identity.signup_verified) {
    await page.goto(base + '/signup');
    await page.locator('input[name="name"]').fill(identity.name);
    await page.locator('input[name="login"]').fill(identity.email);
    await page.locator('input[name="[REDACTED:CREDENTIAL]"]').fill(identity.[REDACTED:CREDENTIAL];
    await page.locator('input[name="confirm-[REDACTED:CREDENTIAL]"]').fill(identity.[REDACTED:CREDENTIAL];
    await page.screenshot({ path: new URL('signup.png', root).pathname, fullPage: true });
    const responsePromise = page.waitForResponse(r => r.url().endsWith('/api/auth/signup') && r.request().method() === 'POST');
    await page.getByRole('button', { name: 'Sign Up', exact: true }).click();
    assert.equal((await responsePromise).status(), 200);
    identity.signup_verified = true;
    await fs.writeFile(identityFile, JSON.stringify(identity));
    await page.waitForURL(url => !url.pathname.includes('signup'));
    await context.close();
  } else {
    await context.close();
  }

  const loginContext = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
  const loginPage = await loginContext.newPage();
  loginPage.on('pageerror', error => errors.push(error.message));
  await loginPage.goto(base + '/login');
  await loginPage.locator('input[name="login"]').fill(identity.email);
  await loginPage.locator('input[name="[REDACTED:CREDENTIAL]"]').fill(identity.[REDACTED:CREDENTIAL];
  const loginPromise = loginPage.waitForResponse(r => r.url().endsWith('/api/auth/login') && r.request().method() === 'POST');
  const alertsLoaded = loginPage.waitForResponse(r => new URL(r.url()).pathname === '/api/alerts' && r.status() === 200);
  await loginPage.locator('button[type="submit"]').click();
  const login = await loginPromise;
  assert.equal(login.status(), 200);
  const headers = { Authorization: 'Bearer ' + (await login.json()).token };
  await loginPage.waitForURL(url => !url.pathname.includes('login'));
  await alertsLoaded;

  if (phase === 'before-restart' && !identity.alert_id) {
    const created = await loginContext.request.post(base + '/api/alert', {
      headers,
      data: {
        resource: '<W2_RUN_RESOURCE_PREFIX>-deployment-verification',
        event: 'DeploymentPersistenceCheck',
        environment: 'Development',
        service: ['WatchOver'],
        severity: 'informational',
        text: 'Verification alert: retained to confirm persistence after a full VM restart.',
        timeout: 0,
      },
    });
    assert.ok([200, 201].includes(created.status()), await created.text());
    identity.alert_id = (await created.json()).id;
    await fs.writeFile(identityFile, JSON.stringify(identity));
  }
  assert.ok(identity.alert_id, 'Saved alert ID must be present');
  const readback = await loginContext.request.get(base + '/api/alert/' + identity.alert_id, { headers });
  assert.equal(readback.status(), 200);
  const saved = (await readback.json()).alert;
  assert.equal(saved.event, 'DeploymentPersistenceCheck');
  assert.equal(saved.resource, '<W2_RUN_RESOURCE_PREFIX>-deployment-verification');
  assert.equal(saved.text, 'Verification alert: retained to confirm persistence after a full VM restart.');
  await loginPage.goto(base + '/alert/' + identity.alert_id);
  await loginPage.getByText('DeploymentPersistenceCheck', { exact: true }).first().waitFor();
  await loginPage.screenshot({ path: new URL(`saved-alert-${phase}.png`, root).pathname, fullPage: true });

  const admin = JSON.parse(await fs.readFile(new URL('../admin-secrets.json', root), 'utf8'));
  const adminLogin = await loginContext.request.post(base + '/api/auth/login', { data: admin });
  assert.equal(adminLogin.status(), 200);
  const claims = JSON.parse(Buffer.from((await adminLogin.json()).token.split('.')[1], 'base64url').toString());
  assert.ok(claims.scope.split(' ').includes('admin'));
  await loginPage.locator('.v-toolbar .v-avatar:visible').first().click();
  await loginPage.getByRole('button', { name: 'Log Out', exact: true }).click();
  await loginPage.waitForURL(url => url.pathname === '/logout');
  await loginPage.goto(base + '/alerts');
  await loginPage.waitForURL(url => url.pathname === '/login');
  assert.deepEqual(errors, []);
  const result = {
    phase, tested_at: new Date().toISOString(), url: base,
    public_dns_addresses: publicAddresses,
    https: 'passed', website_signup: identity.signup_verified ? 'passed' : 'not verified',
    website_login_fresh_browser: 'passed',
