    saved_alert_readback: 'passed', alert_id: identity.alert_id,
    invalid_[REDACTED:CREDENTIAL]_rejected: true, unauthenticated_data_rejected: true,
    administrator_login: 'passed', javascript_errors: errors,
  };
  await fs.writeFile(new URL(`${phase}.json`, root), JSON.stringify(result, null, 2) + '\n');
  console.log(JSON.stringify(result));
} finally { await browser.close(); }
